@Transactional
public Rezervasyon olustur(RezervasyonIstegi req) {
  Oda oda = odaRepo.findByIdForUpdate(req.odaId());
  boolean cakisiyor = rezRepo.existsOverlap(
      oda.getId(), req.giris(), req.cikis());
  if (cakisiyor) {
    throw new OdaDoluException(HttpStatus.CONFLICT);
  }
  return rezRepo.save(Rezervasyon.yeni(oda, req));
}

